import pytest
import torch

import flag_gems

from . import accuracy_utils as utils

# LU decomposition requires high precision; float16/bfloat16 lack mantissa bits for pivoting
SOLVE_EX_DTYPES = [torch.float32]
if flag_gems.runtime.device.support_fp64:
    SOLVE_EX_DTYPES.append(torch.float64)

# Test shapes: (n, nrhs) - identical to tests/test_linalg_solve_ex.py so the
# private primitive is exercised on the same cases as the public
# torch.linalg.solve_ex operator.
SOLVE_EX_SHAPES = [(4, 4), (8, 8), (16, 16), (32, 32)]


def _make_solve_ex_inputs(shape, k, dtype, device):
    """Create well-conditioned A and random B for solve_ex test."""
    n = shape[-1]
    A = torch.randn(*shape, dtype=dtype, device=device)
    eye = torch.eye(n, dtype=dtype, device=device)
    batch_dims = [1] * (A.ndim - 2)
    if batch_dims:
        eye = eye.view(*batch_dims, n, n)
    A = A @ A.mT + eye * n
    B_shape = shape[:-1] + (k,)
    B = torch.randn(*B_shape, dtype=dtype, device=device)
    return A, B


def _assert_solve_ex_outputs(res, ref):
    """Compare (result, info) and check the shape of the parity outputs.

    ``aten::_linalg_solve_ex`` returns (result, LU, pivots, info). The FlagGems
    implementation delegates the solve to the shared ``linalg_solve_ex`` kernel,
    whose contract covers result/info only, so LU and pivots are materialized as
    schema-parity buffers and are not comparable against the native LAPACK
    factorization.
    """
    res_out, res_lu, res_pivots, res_info = res
    ref_out, ref_lu, ref_pivots, ref_info = ref
    utils.gems_assert_close(res_out, ref_out, res_out.dtype)
    assert torch.equal(res_info, ref_info.to(res_info.device))
    assert res_lu.shape == ref_lu.shape
    assert res_pivots.shape == ref_pivots.shape


@pytest.mark.underscore_linalg_solve_ex
@pytest.mark.parametrize("shape", SOLVE_EX_SHAPES)
@pytest.mark.parametrize("dtype", SOLVE_EX_DTYPES)
def test__linalg_solve_ex(shape, dtype):
    n, k = shape
    A, B = _make_solve_ex_inputs((n, n), k, dtype, flag_gems.device)

    ref_A = utils.to_reference(A)
    ref_B = utils.to_reference(B)
    ref = torch._linalg_solve_ex(ref_A, ref_B)
    res = flag_gems._linalg_solve_ex(A, B)

    _assert_solve_ex_outputs(res, ref)


